import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Identify potential drivers based on t-statistics
    t_stats = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical':
            continue  # Skip clinical features for driver selection
        y0 = feats.x[feats.y == 0, i]
        y1 = feats.x[feats.y == 1, i]
        t, _ = stats.ttest_ind(y0, y1, equal_var=False)
        t_stats.append((abs(t), fid))

    # Sort by absolute t-statistic and take top 3
    t_stats.sort(reverse=True)
    drivers = [fid for _, fid in t_stats[:3]]

    # Check for correlated pairs with |r| >= 0.6
    correlations = {}

    # Build correlation matrix
    corr_matrix = np.corrcoef(feats.x.T)

    # Find highly correlated pairs
    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            if abs(corr_matrix[i,j]) >= 0.6:
                fid1, fid2 = feats.ids[i], feats.ids[j]
                correlations[(fid1, fid2)] = corr_matrix[i,j]

    # If no strong correlations, return just drivers
    if not correlations:
        return Design(
            drivers=tuple(drivers),
            columns=tuple(drivers),
            products=(),
            loadings={}
        )

    # Look for product terms involving correlated pairs
    products = []
    for (fid1, fid2), corr in correlations.items():
        # Only consider pairs where both features have strong effect
        if fid1 in drivers and fid2 in drivers:
            products.append((fid1, fid2))

    # If we found product terms, include them
    if products:
        columns = tuple(set([fid for pair in products for fid in pair] + drivers))
        return Design(
            drivers=tuple(drivers),
            columns=columns,
            products=tuple(products),
            loadings={}
        )

    # Otherwise, return just drivers
    return Design(
        drivers=tuple(drivers),
        columns=tuple(drivers),
        products=(),
        loadings={}
    )

